/**
 * @file src/lib/zRingLogic.ts
 * Z-Ring state: unlock crystals from trials. One primary crystal, plus a
 * second crystal once fighter mastery tier 55 (z_power_double_use) is owned.
 */

import { coerceStr } from './coerceStr.ts';
import {
    isZCrystalId,
    type ZCrystalId,
    Z_CRYSTAL_IDS,
    Z_POWER_EFFECT_MULT,
    Z_RING_DARKINIUM_ULT_DRAIN_FRAC,
    Z_RING_ELECTRIUM_FIRST_ATK_DMG_FRAC,
    Z_RING_FIRIUM_BURN_TICK_FRAC,
    Z_RING_FIRIUM_ENEMY_DAMAGE_FRAC,
    Z_RING_GRASSIUM_HEAL_FRAC,
    Z_RING_GROUNDIUM_FIRST_HIT_REDUCTION_FRAC,
    Z_RING_NORMALIUM_SPEED_FRAC,
    Z_RING_WATERIUM_SWITCH_HEAL_FRAC,
} from '../../constants/balance/zRing.ts';
import type { GameRuntime } from '../types/game.js';
import type { ZRingCombatState, ZRingState } from '../types/game/state.js';

export function createDefaultZRingState(): ZRingState {
    return {
        unlockedCrystalIds: [],
        activeCrystalId: null,
        secondaryCrystalId: null,
        introShown: false,
    };
}

function resolveSecondaryId(
    unlocked: readonly string[],
    active: ZCrystalId | null,
    raw: unknown,
): ZCrystalId | null {
    if (raw == null) return null;
    const id = coerceStr(raw, '');
    if (!isZCrystalId(id)) return null;
    if (!unlocked.includes(id) || id === active) return null;
    return id;
}

export function normalizeZRingState(raw: unknown): ZRingState {
    const base = createDefaultZRingState();
    if (!raw || typeof raw !== 'object') return base;
    const o = raw as Record<string, unknown>;
    const unlocked = Array.isArray(o.unlockedCrystalIds)
        ? o.unlockedCrystalIds.filter((id): id is ZCrystalId => isZCrystalId(coerceStr(id, '')))
        : [];
    const activeId = coerceStr(o.activeCrystalId, '');
    const active = o.activeCrystalId != null && isZCrystalId(activeId)
        ? activeId
        : null;
    const unique = [...new Set(unlocked)];
    const activeCrystalId = active && unique.includes(active) ? active : (unique[0] ?? null);
    return {
        unlockedCrystalIds: unique,
        activeCrystalId,
        secondaryCrystalId: resolveSecondaryId(unique, activeCrystalId, o.secondaryCrystalId),
        introShown: o.introShown === true,
    };
}

export function getZRingState(game: GameRuntime): ZRingState {
    if (!game.zRingState || typeof game.zRingState !== 'object') {
        game.zRingState = createDefaultZRingState();
    }
    return game.zRingState;
}

export function isZRingUnlocked(game: GameRuntime): boolean {
    const state = game.zRingState;
    return !!(state && state.unlockedCrystalIds.length > 0);
}

export function isZCrystalUnlocked(game: GameRuntime, crystalId: string): boolean {
    const state = getZRingState(game);
    return state.unlockedCrystalIds.includes(crystalId);
}

export function unlockZCrystal(game: GameRuntime, crystalId: string): boolean {
    if (!isZCrystalId(crystalId)) return false;
    const state = getZRingState(game);
    if (state.unlockedCrystalIds.includes(crystalId)) return false;
    state.unlockedCrystalIds = [...state.unlockedCrystalIds, crystalId];
    if (!state.activeCrystalId) state.activeCrystalId = crystalId;
    return true;
}

export function setActiveZCrystal(game: GameRuntime, crystalId: string): boolean {
    if (!isZCrystalId(crystalId)) return false;
    const state = getZRingState(game);
    if (!state.unlockedCrystalIds.includes(crystalId)) return false;
    state.activeCrystalId = crystalId;
    if (state.secondaryCrystalId === crystalId) state.secondaryCrystalId = null;
    return true;
}

export function hasSecondZCrystalSlot(game: GameRuntime): boolean {
    if (typeof game.getMasteryBonus !== 'function') return false;
    return (Number(game.getMasteryBonus('z_power_double_use')) || 0) > 0;
}

/** Stored second crystal, or null when the mastery slot is not owned. */
export function getSecondaryZCrystalId(game: GameRuntime): ZCrystalId | null {
    if (!hasSecondZCrystalSlot(game)) return null;
    const state = game.zRingState;
    if (!state) return null;
    return resolveSecondaryId(state.unlockedCrystalIds, getActiveZCrystalId(game), state.secondaryCrystalId);
}

export function isZCrystalEquipped(game: GameRuntime, crystalId: string): boolean {
    if (!isZCrystalId(crystalId)) return false;
    if (getActiveZCrystalId(game) === crystalId) return true;
    return getSecondaryZCrystalId(game) === crystalId;
}

export function setSecondaryZCrystal(game: GameRuntime, crystalId: string): boolean {
    if (!isZCrystalId(crystalId)) return false;
    const state = getZRingState(game);
    if (!state.unlockedCrystalIds.includes(crystalId)) return false;
    if (crystalId === getActiveZCrystalId(game)) return false;
    if (state.secondaryCrystalId === crystalId) return false;
    state.secondaryCrystalId = crystalId;
    return true;
}

export function clearSecondaryZCrystal(game: GameRuntime): boolean {
    const state = getZRingState(game);
    if (!state.secondaryCrystalId) return false;
    state.secondaryCrystalId = null;
    return true;
}

export function getActiveZCrystalId(game: GameRuntime): ZCrystalId | null {
    const state = game.zRingState;
    if (!state?.activeCrystalId || !isZCrystalId(state.activeCrystalId)) return null;
    if (!state.unlockedCrystalIds.includes(state.activeCrystalId)) return null;
    return state.activeCrystalId;
}

/** Special PVP / structured modes where mid-fight crystal swap is blocked. */
export function isZRingSpecialCombat(game: GameRuntime): boolean {
    if (game.towerState?.isActive) return true;
    if (game.arenaState?.active) return true;
    if (game.gymTrainerState?.active) return true;
    if (game.subwayState?.isActive) return true;
    if (game.championsTowerState?.isActive) return true;
    return false;
}

/**
 * Z-Crystal combat effects are active in zone wild and all PVP modes.
 * @deprecated Prefer isZRingEffectsActive — kept as alias for older call sites.
 */
export function isZRingZoneCombat(_game: GameRuntime): boolean {
    return true;
}

/** Effects run in zone farm and PVP (arena, tower, subway, gym, champions tower). */
export function isZRingEffectsActive(_game: GameRuntime): boolean {
    return true;
}

/** Team-tab Z-Ring config blocked during special PVP combat modes. */
export function canConfigureZRing(game: GameRuntime): boolean {
    return !isZRingSpecialCombat(game);
}

/** Zone wild only — used by capture-only crystals (Grassium). */
export function isZRingWildCaptureCombat(game: GameRuntime): boolean {
    return !isZRingSpecialCombat(game);
}

export function createDefaultZRingCombatState(): ZRingCombatState {
    return {
        groundiumGuardUsed: false,
        electriumFirstAtkUsed: false,
        grassiumRetryUsed: false,
        grassiumFreeThrowPending: false,
        enemyAtbSkips: 0,
    };
}

export function resetZRingCombatState(game: GameRuntime): void {
    game.zRingCombat = createDefaultZRingCombatState();
}

export function hasMaitreAlolaForZPower(game: GameRuntime): boolean {
    if (typeof game.hasBadge === 'function') return game.hasBadge('maitre_alola');
    return !!game.badges?.maitre_alola;
}

export function getZEffectMultiplier(game: GameRuntime): number {
    if (!isZRingEffectsActive(game)) return 1;
    if (hasMaitreAlolaForZPower(game)) return Z_POWER_EFFECT_MULT;
    return 1;
}

/** Effective percents shown on the Z-Ring, using the same formulas as combat. */
export function getZCrystalEffectTemplateVars(game: GameRuntime): Record<string, number> {
    const mult = getZEffectMultiplier(game);
    const firiumKeep = Math.max(0.1, 1 - Z_RING_FIRIUM_ENEMY_DAMAGE_FRAC * mult);
    const guard = Math.min(0.9, Z_RING_GROUNDIUM_FIRST_HIT_REDUCTION_FRAC * mult);
    return {
        speed: Math.round(Z_RING_NORMALIUM_SPEED_FRAC * mult * 100),
        switchHeal: Math.round(Z_RING_WATERIUM_SWITCH_HEAL_FRAC * mult * 100),
        tick: Math.round(Z_RING_FIRIUM_BURN_TICK_FRAC * mult * 100),
        reduction: Math.round((1 - firiumKeep) * 100),
        heal: Math.round(Z_RING_GRASSIUM_HEAL_FRAC * mult * 100),
        damage: Math.round(Z_RING_ELECTRIUM_FIRST_ATK_DMG_FRAC * mult * 100),
        skips: Math.floor(1 * mult),
        drain: Math.round(Z_RING_DARKINIUM_ULT_DRAIN_FRAC * mult * 100),
        guard: Math.round(guard * 100),
    };
}

export function badgeToZCrystalId(badge: string): ZCrystalId | null {
    return isZCrystalId(badge) ? badge : null;
}

export function syncZCrystalsFromAlolaBadges(game: GameRuntime): void {
    for (const id of Z_CRYSTAL_IDS) {
        const has = typeof game.hasBadge === 'function'
            ? game.hasBadge(id)
            : !!game.badges?.[id];
        if (has) unlockZCrystal(game, id);
    }
}
